// Exercise actual generated bytes with the production loader, parked replacements, LOD and street/collider placement.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as THREE from 'three';
import { createContext } from '../js/core/ctx.js';
import { VehicleLibrary, loadVehicles, vehicleMatrix } from '../js/world/vehicle-library.js';
import { car, moto, bicycle, MOTO_SEAT_REST } from '../js/world/vehicles.js';
import { OCC, buildOccupancy } from '../js/world/occupancy.js';
import { makePlan } from './world-lib.mjs';
import { project } from '../js/world/geom.js';
import { inSpawnFan } from '../js/world/kit.js';
import { buildData, loadVehiclesFromDisk, readAssetJson } from './headless.mjs';

async function loaded() {
  const ctx = createContext({ headless: true });
  await ctx.assets.init(readAssetJson);
  await loadVehiclesFromDisk(ctx);
  return ctx;
}

test('large vehicle reservations remain visible to distant occupancy queries', () => {
  const { plan } = makePlan(), occ = buildOccupancy(plan);
  assert.ok(occ.take(1, 1, 8));
  assert.equal(occ.overlaps(10, 1, 1.5), true, 'the query crosses the 3m search radius formerly assumed by the spatial hash');
  assert.equal(occ.overlaps(12, 1, 1), false);
});

test('all ten actual vehicles load with a cheaper real LOD; wheel/body parts share a material batch', async () => {
  const ctx = await loaded();
  assert.equal(ctx.vehicleLibrary.types.size, 10);
  for (const type of ctx.vehicleLibrary.types.values()) {
    assert.equal(type.triangles[0], type.meta.triangles, type.key);
    assert.equal(type.triangles[1], ctx.assets.meta(type.meta.lod1).triangles, type.meta.lod1);
    assert.ok(type.triangles[0] <= 6000 && type.triangles[1] <= 600 && type.triangles[1] < type.triangles[0]);
    for (const parts of type.parts) assert.equal(parts.length, new Set(parts.map((p) => p.matKey)).size);
    const raw = ctx.assets.parts(type.key);
    assert.ok(raw.length > type.parts[0].length, 'separate source wheel nodes are merged for parked rendering');
  }
});

test('metadata without a loaded GLB leaves the complete procedural vehicles intact', async () => {
  const ctx = createContext({ headless: true });
  await ctx.assets.init(readAssetJson);
  ctx.vehicleLibrary = new VehicleLibrary(ctx);
  assert.equal(ctx.vehicleLibrary.types.size, 0);
  for (const [fn, minimum] of [[car, 1200], [moto, 1200], [bicycle, 800]]) {
    const b = ctx.batch.builder('fallback-' + fn.name);
    fn({ ctx }, b, 0, 0, 0, .3, .08, { hex: 0xb8222a });
    assert.ok(b.tris >= minimum, `${fn.name} still has working geometry`);
  }
  assert.equal(ctx.vehicleLibrary.records.length, 0);
  assert.equal(ctx.assets.missing.size, 0, 'no missing-asset cube is accepted');
});

test('a missing low node or unknown material refuses only the affected replacement', async () => {
  const ctx = await loaded(), key = 'vehicle_pickup';
  const meta = ctx.assets.meta(key), gl = ctx.assets.loaded.get(meta.glb);
  gl.scene.getObjectByName(meta.lod1).removeFromParent();
  const lib = new VehicleLibrary(ctx);
  assert.equal(lib.has(key), false);
  assert.equal(lib.has('vehicle_bicycle'), true);
  const bicycleParts = ctx.assets.parts('vehicle_bicycle');
  const old = bicycleParts[0].matKey;
  bicycleParts[0].matKey = 'unknown_vehicle_material';
  const broken = new VehicleLibrary(ctx);
  assert.equal(broken.has('vehicle_bicycle'), false);
  bicycleParts[0].matKey = old;
});

test('disabled or failed library download uses fallback and records failed files', async () => {
  const ctx = createContext({ vehicles: false });
  await ctx.assets.init(readAssetJson);
  const requested = [];
  ctx.assets.load = async (path) => { requested.push(path); throw new Error('simulated offline file'); };
  assert.equal(await loadVehicles(ctx), null); assert.equal(requested.length, 0);
  ctx.opts.vehicles = true;
  assert.equal(await loadVehicles(ctx), null); assert.equal(requested.length, 2);
  assert.ok(requested.every((path) => path.startsWith('vehicles/')), 'the workshop furniture motorbike shares a tag but is not loaded by this library');
  assert.equal(ctx.world.vehicleLoad.assets, 0);
  assert.equal(ctx.world.vehicleLoad.failed.length, ctx.world.vehicleLoad.files);
});

test('near -> far -> culled -> near teleports never draw both LODs; repainting does not add batches', async () => {
  const ctx = await loaded(), C = ctx.vehicleLibrary, key = 'vehicle_hatchback_a';
  ctx.camera = new THREE.PerspectiveCamera(); ctx.camera.position.set(0, 1.6, 6);
  assert.ok(C.place(key, 0, 0, 0, 0, 0, { paint: 0 }));
  assert.ok(C.place(key, 3, 0, 0, 0, 0, { paint: 12 }));
  assert.equal(C.place(key, NaN, 0, 0), false);
  C.finalize();
  const type = C.types.get(key), nearTriangles = C.stats.triangles;
  assert.equal(C.stats.near, 2); assert.equal(C.stats.far, 0);
  assert.equal(C.batches.length, type.parts[0].length + type.parts[1].length);
  const painted = type.meshes[0].find((m) => m.geometry.attributes.vehiclePaintTile);
  assert.deepEqual([...painted.geometry.attributes.vehiclePaintTile.array], [0, 12]);
  assert.ok(type.meshes[0].every((m) => m.count === 2 && m.visible && !m.castShadow));
  assert.ok(type.meshes[1].every((m) => m.count === 0 && !m.visible));
  ctx.camera.position.set(0, 1.6, 55); ctx.events.emit('player:teleport', {});
  assert.equal(C.stats.near, 0); assert.equal(C.stats.far, 2);
  assert.ok(C.stats.triangles <= 1200 && C.stats.triangles < nearTriangles / 3);
  assert.ok(type.meshes[0].every((m) => m.count === 0 && !m.visible));
  assert.ok(type.meshes[1].every((m) => m.count === 2 && m.visible));
  ctx.camera.position.set(0, 1.6, 180); ctx.events.emit('player:teleport', {});
  assert.equal(C.stats.culled, 2); assert.equal(C.stats.triangles, 0);
  assert.ok(C.batches.every((m) => !m.visible && m.count === 0));
  ctx.camera.position.set(0, 1.6, 6); ctx.events.emit('player:teleport', {});
  assert.equal(C.stats.near, 2);
  assert.equal(C.place(key, 8, 0, 0), false, 'a finalized fixed library refuses unallocated instance slots');
});

test('generated motorbike replacements keep helmets on the exact pitched seat and do not draw fallback', async () => {
  const ctx = await loaded(), b = ctx.batch.builder('moto-test');
  const key = moto({ ctx }, b, 12, 3, -7, .8, .12, { hex: 0x2b4f7e });
  assert.equal(key, 'vehicle_motorbike'); assert.equal(b.tris, 0);
  assert.equal(ctx.vehicleLibrary.records.length, 1);
  const rest = ctx.vehicleLibrary.meta(key).seatRest ?? MOTO_SEAT_REST;
  const want = new THREE.Vector3(0, rest.y, rest.z).applyMatrix4(vehicleMatrix(12, 3, -7, .8, .12));
  const seat = ctx.world.motoSeats[0];
  assert.ok(new THREE.Vector3(seat.x, seat.y, seat.z).distanceTo(want) < 1e-6);
  assert.ok(Math.abs(seat.pitch - (.12 - rest.tilt)) < 1e-6);
});

test('the real world places every design; extra vehicles fit streets, keep nav/door clearances and use solid colliders', async () => {
  const { ctx, plan } = await buildData({ world: true, furnish: false });
  const lib = ctx.vehicleLibrary;
  assert.equal(lib.types.size, 10);
  assert.equal(new Set(lib.records.map((r) => r.key)).size, 10, JSON.stringify(ctx.world.vehicles));
  assert.ok(lib.records.length >= 40);
  assert.ok(lib.records.some((r) => r.key === 'vehicle_chiva'));
  assert.ok(lib.records.some((r) => r.key === 'vehicle_motorbike'));
  const additions = lib.records.filter((r) => r.source === 'addition');
  assert.equal(additions.length, 5);
  for (const rec of additions) {
    const meta = lib.meta(rec.key), st = plan.streets.find((s) => s.id === rec.street);
    assert.ok(st && st.kind !== 'stair' && st.width >= meta.footprint[0] + 2.4);
    assert.equal(inSpawnFan(plan, rec.x, rec.z, Math.hypot(...meta.footprint) / 2), false);
    const [w, d] = meta.footprint, c = Math.cos(rec.yaw), s = Math.sin(rec.yaw);
    for (let i = 0; i <= 4; i++) for (let j = 0; j <= 8; j++) {
      const lx = (i / 4 - .5) * w, lz = (j / 8 - .5) * d;
      const x = rec.x + lx * c + lz * s, z = rec.z - lx * s + lz * c;
      assert.ok(project(st._d.pts, st._d.cum, x, z).d <= st.width / 2 - .14, rec.key + ': inside kerb');
      assert.ok(ctx.world.occ.navDist(x, z) >= .89, rec.key + ': leaves walking routes clear');
      assert.equal(ctx.world.occ.at(x, z) & (OCC.DOOR | OCC.STAIR | OCC.LOT | OCC.PLAZA), 0, rec.key + ': no doorway or building overlap');
    }
    assert.ok(ctx.physics._overlaps(rec.x, rec.z, rec.y, .24, 1.64), rec.key + ': solid collider covers its centre');
  }
  assert.deepEqual(ctx.errors, []);
  assert.equal(ctx.matlib.missing.size, 0);
});
